script:
(function () {
  'use strict';
  // Debt inventory: everything you owe in one place.
  //   Total owed = sum of balances. Weighted average APR = sum(balance x APR) / total owed.
  //   Monthly interest at today's balances = sum(balance x APR / 12); interest share of payments =
  //   that interest / total monthly payments.
  //   Debt-free date: each debt is paid at its own fixed payment, with no rollover - each month
  //   interest = balance x APR / 12 (rounded to the cent) is added, then the payment (capped at
  //   what is owed). The debt-free date is when the last debt is cleared.
  // Verified (scratchpad b5debt/math.test.js):
  //   weighted APR of $1,000 at 10% and $3,000 at 20% = 17.5%; monthly interest on those =
  //   (100 + 600) / 12 = $58.33;
  //   $10,000 at 12% paid $222.45 -> 60 months, interest within $0.10 of the closed form $3,346.67 (60 x 222.4445 - 10,000);
  //   $2,400 at 0% paid $100 -> 24 months; the type summary adds up to the grand totals;
  //   a payment at or below the first month's interest is reported by name, never as a result.
  var MAX_MONTHS = 1200;
  var MAX_DEBTS = 15;
  var TYPES = ['Credit card', 'Mortgage', 'Home equity loan or HELOC', 'Auto loan', 'Student loan', 'Personal loan', 'Medical bill', 'Other'];
  var DEFAULTS = [
    { type: 'Mortgage', name: 'Home mortgage', balance: 245000, apr: 6.25, pay: 1580 },
    { type: 'Auto loan', name: 'Car loan', balance: 18500, apr: 7.2, pay: 420 },
    { type: 'Student loan', name: 'Student loan', balance: 27000, apr: 5.8, pay: 310 },
    { type: 'Credit card', name: 'Visa card', balance: 6400, apr: 23.99, pay: 190 },
    { type: 'Medical bill', name: 'Hospital bill', balance: 1200, apr: 0, pay: 100 }
  ];
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var monthName = new Intl.DateTimeFormat('en-US', { month: 'short', year: 'numeric' });
  var rowCounter = 0;

  // ---- Calculation ----
  function cents(x) { return Math.round(x * 100) / 100; }

  function payoff(debt) {
    var bal = debt.balance, total = 0;
    for (var m = 1; m <= MAX_MONTHS; m++) {
      var interest = cents(bal * debt.apr / 12);
      bal += interest; total += interest;
      bal = cents(bal - Math.min(debt.pay, bal));
      if (bal <= 0.005) return { paidOff: true, months: m, interest: total };
    }
    return { paidOff: false, months: MAX_MONTHS, interest: total };
  }

  function summarize(debts) {
    var s = { owed: 0, weighted: 0, pay: 0, interest: 0 };
    debts.forEach(function (d) {
      s.owed += d.balance; s.weighted += d.balance * d.apr; s.pay += d.pay; s.interest += d.balance * d.apr / 12;
    });
    s.avgApr = s.owed > 0 ? s.weighted / s.owed : 0;
    s.interestShare = s.pay > 0 ? Math.min(s.interest / s.pay, 1) : 0;
    return s;
  }

  // ---- Page ----
  function duration(months) {
    var y = Math.floor(months / 12), m = months % 12, parts = [];
    if (y) parts.push(y + (y === 1 ? ' year' : ' years'));
    if (m || !y) parts.push(m + (m === 1 ? ' month' : ' months'));
    return parts.join(' ');
  }

  function dateAfter(months) {
    var now = new Date();
    return monthName.format(new Date(now.getFullYear(), now.getMonth() + months, 1));
  }

  function set(id, text) { document.getElementById(id).textContent = text; }

  function clearBody(id) {
    var body = document.getElementById(id);
    while (body.firstChild) body.removeChild(body.firstChild);
    return body;
  }

  function addRow(body, cells) {
    var tr = document.createElement('tr');
    cells.forEach(function (text) {
      var td = document.createElement('td');
      td.textContent = text;
      tr.appendChild(td);
    });
    body.appendChild(tr);
  }

  function el(tag, className, text) {
    var e = document.createElement(tag);
    if (className) e.className = className;
    if (text) e.textContent = text;
    return e;
  }

  function numberField(id, label, value, affix, affixFirst, step, max) {
    var wrap = el('div');
    var lab = el('label', 'form-label', label);
    lab.setAttribute('for', id);
    var group = el('div', 'input-group');
    var input = el('input', 'min-w-0 flex-1 bg-transparent px-3 text-[15px] tabular-nums text-ink focus:outline-none');
    input.type = 'number'; input.id = id; input.min = '0'; input.step = step; input.inputMode = 'decimal';
    if (max) input.max = max;
    input.value = value === '' ? '' : String(value);
    var a = el('span', 'input-affix', affix);
    if (affixFirst) { group.appendChild(a); group.appendChild(input); } else { group.appendChild(input); group.appendChild(a); }
    wrap.appendChild(lab); wrap.appendChild(group);
    return wrap;
  }

  function addDebtRow(d) {
    var list = document.getElementById('hmoDebts');
    rowCounter++;
    var n = rowCounter;
    var row = el('div', 'space-y-3 rounded-xl border border-line p-4');
    row.setAttribute('data-debt-row', String(n));
    var head = el('div', 'flex flex-wrap items-center justify-between gap-2');
    var title = el('p', 'text-sm font-semibold text-ink', 'Debt');
    title.setAttribute('data-debt-title', '');
    var remove = el('button', 'button-secondary h-9 px-3 text-sm', 'Remove');
    remove.type = 'button';
    remove.setAttribute('data-remove', '');
    remove.addEventListener('click', function () {
      if (list.querySelectorAll('[data-debt-row]').length <= 1) return;
      row.remove();
      refreshRows(); update();
    });
    head.appendChild(title); head.appendChild(remove);
    row.appendChild(head);

    var top = el('div', 'form-row form-row-2');
    var typeWrap = el('div');
    var typeLabel = el('label', 'form-label', 'Type');
    typeLabel.setAttribute('for', 'hmoType' + n);
    var select = el('select', 'form-select');
    select.id = 'hmoType' + n;
    TYPES.forEach(function (t) {
      var o = el('option', '', t);
      o.value = t;
      select.appendChild(o);
    });
    select.value = d.type || 'Credit card';
    typeWrap.appendChild(typeLabel); typeWrap.appendChild(select);
    var nameWrap = el('div');
    var nameLabel = el('label', 'form-label', 'Name');
    nameLabel.setAttribute('for', 'hmoName' + n);
    var name = el('input', 'form-control');
    name.type = 'text'; name.id = 'hmoName' + n; name.maxLength = 40; name.autocomplete = 'off';
    name.placeholder = 'e.g. Store card';
    name.value = d.name || '';
    nameWrap.appendChild(nameLabel); nameWrap.appendChild(name);
    top.appendChild(typeWrap); top.appendChild(nameWrap);
    row.appendChild(top);

    var pair = el('div', 'form-row form-row-2');
    pair.appendChild(numberField('hmoBal' + n, 'Balance', d.balance, '$', true, '100'));
    pair.appendChild(numberField('hmoApr' + n, 'APR', d.apr, '%', false, '0.1', '100'));
    row.appendChild(pair);
    row.appendChild(numberField('hmoPay' + n, 'Monthly payment', d.pay, '$', true, '10'));
    list.appendChild(row);
    refreshRows();
  }

  function refreshRows() {
    var rows = document.getElementById('hmoDebts').querySelectorAll('[data-debt-row]');
    rows.forEach(function (row, i) {
      row.querySelector('[data-debt-title]').textContent = 'Debt ' + (i + 1);
      var rm = row.querySelector('[data-remove]');
      rm.disabled = rows.length <= 1;
      rm.setAttribute('aria-label', 'Remove debt ' + (i + 1));
    });
    document.getElementById('hmoAdd').disabled = rows.length >= MAX_DEBTS;
    document.getElementById('hmoCount').textContent = rows.length + ' of ' + MAX_DEBTS + ' rows used.';
  }

  function readDebts() {
    var out = [], ok = true;
    var rows = document.getElementById('hmoDebts').querySelectorAll('[data-debt-row]');
    rows.forEach(function (row, i) {
      var n = row.getAttribute('data-debt-row');
      var type = document.getElementById('hmoType' + n).value;
      if (TYPES.indexOf(type) < 0) type = 'Other';
      var name = document.getElementById('hmoName' + n).value.trim() || ('Debt ' + (i + 1));
      var balEl = document.getElementById('hmoBal' + n), aprEl = document.getElementById('hmoApr' + n), payEl = document.getElementById('hmoPay' + n);
      var bal = parseFloat(balEl.value), apr = aprEl.value.trim() === '' ? 0 : parseFloat(aprEl.value), pay = parseFloat(payEl.value);
      if (balEl.value.trim() === '' || bal === 0) {
        [balEl, aprEl, payEl].forEach(function (e) { e.setAttribute('aria-invalid', 'false'); });
        return;
      }
      var badBal = isNaN(bal) || bal < 0 || bal > 1e9, badApr = isNaN(apr) || apr < 0 || apr > 100, badPay = isNaN(pay) || pay <= 0;
      balEl.setAttribute('aria-invalid', String(badBal));
      aprEl.setAttribute('aria-invalid', String(badApr));
      payEl.setAttribute('aria-invalid', String(badPay));
      if (badBal || badApr || badPay) { ok = false; return; }
      out.push({ type: type, name: name, balance: bal, apr: apr / 100, pay: pay });
    });
    return { ok: ok, debts: out };
  }

  function clearResults() {
    ['hmoOwed', 'hmoPayments', 'hmoAvgApr', 'hmoInterest', 'hmoDate', 'hmoLeft'].forEach(function (id) { set(id, '–'); });
    set('hmoInterestNote', ''); set('hmoDateNote', ''); set('hmoLeftNote', '');
    clearBody('hmoByType'); clearBody('hmoList');
  }

  function aprText(apr) { return (apr * 100).toFixed(2) + '%'; }

  function update() {
    var error = document.getElementById('hmoError');
    var input = readDebts();
    var problem = '';
    if (!input.ok) problem = 'Check the highlighted debts: balances of $0 or more, APRs from 0 to 100% and monthly payments above $0.';
    else if (!input.debts.length) problem = 'Enter at least one debt with a balance above $0.';
    var debts = input.debts, plans = [];
    if (!problem) {
      for (var k = 0; k < debts.length; k++) {
        var p = payoff(debts[k]);
        if (!p.paidOff) {
          problem = 'The payment on ' + debts[k].name + ' does not cover enough of its interest to pay it off within 100 years. Raise that payment.';
          break;
        }
        plans.push(p);
      }
    }
    if (problem) { error.hidden = false; error.textContent = problem; clearResults(); return; }
    error.hidden = true; error.textContent = '';

    var s = summarize(debts), lastMonth = 0, interestLeft = 0;
    plans.forEach(function (p) { lastMonth = Math.max(lastMonth, p.months); interestLeft += p.interest; });
    set('hmoOwed', money.format(s.owed));
    set('hmoPayments', money.format(s.pay));
    set('hmoAvgApr', aprText(s.avgApr));
    set('hmoInterest', money.format(s.interest));
    set('hmoInterestNote', Math.round(s.interestShare * 100) + '% of your monthly payments goes to interest.');
    set('hmoDate', dateAfter(lastMonth));
    set('hmoDateNote', 'In ' + duration(lastMonth) + ' if you keep paying what you pay now.');
    set('hmoLeft', money.format(interestLeft));
    set('hmoLeftNote', 'You will pay ' + money.format(s.owed + interestLeft) + ' in all.');

    var byType = clearBody('hmoByType');
    TYPES.forEach(function (t) {
      var group = debts.filter(function (d) { return d.type === t; });
      if (!group.length) return;
      var g = summarize(group);
      addRow(byType, [t, String(group.length), money.format(g.owed), Math.round(g.owed / s.owed * 1000) / 10 + '%', aprText(g.avgApr), money.format(g.pay), money.format(g.interest)]);
    });
    addRow(byType, ['All debts', String(debts.length), money.format(s.owed), '100%', aprText(s.avgApr), money.format(s.pay), money.format(s.interest)]);

    var order = debts.map(function (d, i) { return i; }).sort(function (a, b) { return (debts[b].apr - debts[a].apr) || (a - b); });
    var list = clearBody('hmoList');
    order.forEach(function (i) {
      var d = debts[i], p = plans[i];
      addRow(list, [d.name, d.type, money.format(d.balance), aprText(d.apr), money.format(d.pay), money.format(d.balance * d.apr / 12),
        dateAfter(p.months), money.format(p.interest)]);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    DEFAULTS.forEach(addDebtRow);
    var form = document.getElementById('hmoForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    document.getElementById('hmoAdd').addEventListener('click', function () {
      if (document.getElementById('hmoDebts').querySelectorAll('[data-debt-row]').length >= MAX_DEBTS) return;
      addDebtRow({ type: 'Credit card', name: '', balance: '', apr: '', pay: '' });
      update();
    });
    update();
  });
})();
